// Geminiの返答テキスト（JSON文字列）を取り出す（入る場所の候補を順に見る）
let raw = $json.content?.parts?.[0]?.text ?? $json.candidates?.[0]?.content?.parts?.[0]?.text ?? $json.text ?? $json.response ?? $json.output ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let p = {};
try {
  p = JSON.parse(raw);
} catch (e) {
  p = { summary: '', decisions: '', todos: '', carryover: '', _parse_error: String(e), _raw: raw };
}
const fileName = $('Google Driveトリガー（録音フォルダ）').item.json.name || '';
return [{ json: {
  "日付": $now.toFormat('yyyy-MM-dd'),
  "ファイル名": fileName,
  "要約": p.summary || '',
  "決定事項": p.decisions || '',
  "宿題": p.todos || '',
  "持ち越し": p.carryover || ''
} }];
